<section class="auth-section container"><div class="auth-intro"><div class="eyebrow"><?= t('موبايلك هو مفتاحك','YOUR PHONE IS YOUR KEY') ?></div><h1><?= t('أهلاً بك في <em>حصاد.</em>','Welcome to <em>Hasad.</em>') ?></h1><p><?= t('الدخول الأساسي برقم الموبايل ورمز تحقق. بيانات المورد والمصنع تظل منفصلة، وحصاد هو نقطة التنسيق الوحيدة.','Standard access uses a phone and verification code. Supplier and factory data stay separate; Hasad is the sole coordination point.') ?></p><div class="auth-art"><?= icon('sprout') ?><span>✦</span></div></div><div class="auth-stack"><form class="form-card auth-card" method="post" action="<?= e(url('login')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="phone-start"><h2><?= t('دخول / حساب جديد','Sign in / create account') ?></h2><?php field(t('الاسم','Name'),'name','text','','required maxlength="160" autocomplete="name"');field(t('رقم الموبايل المصري','Egyptian mobile number'),'phone','tel','','required maxlength="30" autocomplete="tel" placeholder="01012345678" dir="ltr"');select_field(t('نوع الحساب','Account type'),'account_type',['seller'=>t('مورد مخلفات','Residue supplier'),'buyer'=>t('مصنع / مشتري','Factory / buyer')]); ?><label class="consent"><input type="checkbox" name="consent" value="yes" required><span><?= t('أوافق على رمز الدخول وسياسة الخصوصية.','I agree to the sign-in code and privacy policy.') ?></span></label><button class="button button-green button-full"><?= t('إرسال رمز الدخول','Send sign-in code') ?><?= icon('arrow') ?></button></form><?php if(demo_mode()): ?><form class="form-card auth-card training-login" method="post" action="<?= e(url('login')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="demo-login"><div class="eyebrow"><?= t('وضع العرض والتدريب','DEMO / TRAINING MODE') ?></div><h2><?= t('دخول شخصية تدريبية','Training persona sign-in') ?></h2><p class="caption"><?= t('استخدم البيانات التي يسلّمها مقدم العرض. لا توجد بيانات دخول داخل المستودع.','Use credentials supplied by the presenter. No credentials are stored in the repository.') ?></p><?php select_field(t('الشخصية','Persona'),'persona',['supplier'=>t('المورد','Supplier'),'buyer'=>t('المصنع / المشتري','Factory / buyer')]);field(t('رقم الموبايل التدريبي','Training phone'),'phone','tel','','required maxlength="30" dir="ltr"');field(t('كلمة مرور التدريب','Training password'),'password','password','','required minlength="12" autocomplete="off"'); ?><button class="button button-gold button-full"><?= t('فتح السيناريو التدريبي','Open training scenario') ?></button></form><?php endif; ?></div></section>
